@dataclass(frozen=True)
class App:
    name: str
    slug: str
    display_name: str
    first_release: int = 100
    checkout_submodules: bool = False
    requires_msvc: bool = False

    @property
    def project(self) -> str:
        return f"{self.name}/src/{self.name}.csproj"

    @property
    def buildnumber(self) -> str:
        return f"{self.name}/buildnumber.txt"


@dataclass(frozen=True)
class Profile:
    id: str
    display_name: str
    build_source: str
    publish_aot: bool
    self_contained: bool
    legacy_names: bool


@dataclass
class AppPackage:
    app: App
    profile: Profile
    version: int
    zip_path: Path
    source: str
    commit_hash: str


@dataclass(frozen=True)
class CommitEntry:
    full_sha: str
    short_sha: str
    subject: str
    paths: tuple[str, ...] = ()


@dataclass(frozen=True)
class PublishedAppAsset:
    release_tag: str
    version: int
    file_name: str
    digest: str


@dataclass(frozen=True)
class PullRequestEntry:
    number: int
    title: str
    author_username: str
    url: str


REPO_ROOT = Path(__file__).resolve().parents[2]
