APP_CATALOG_PATH = REPO_ROOT / "apps.json"
APP_NAME_PATTERN = re.compile(r"^[A-Za-z][A-Za-z0-9]*$")
APP_SLUG_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def load_app_catalog(path: Path = APP_CATALOG_PATH) -> list[App]:
    try:
        entries = json.loads(path.read_text(encoding="utf-8"))["apps"]
    except (OSError, ValueError, KeyError, TypeError) as error:
        raise SystemExit(f"Could not read the app catalog {path}: {error}") from error

    apps: list[App] = []
    for entry in entries:
        app = App(
            name=str(entry["name"]),
            slug=str(entry["slug"]),
            display_name=str(entry["displayName"]),
            first_release=int(entry["firstRelease"]),
            checkout_submodules=entry["checkoutSubmodules"] is True,
            requires_msvc=entry["requiresMsvc"] is True,
        )
        if not APP_NAME_PATTERN.fullmatch(app.name) or not APP_SLUG_PATTERN.fullmatch(app.slug):
            raise SystemExit(f"Invalid app catalog entry in {path}: {entry!r}")
        apps.append(app)

    names = [app.name for app in apps]
    slugs = [app.slug for app in apps]
    if not apps or len(set(names)) != len(names) or len(set(slugs)) != len(slugs):
        raise SystemExit(f"The app catalog {path} must list at least one app, each name and slug once.")
    return apps


