def third_party_notice_archive_files(app_name: str | None = None) -> tuple[str, ...]:
    """The .notices entries a package must carry: the shared set, plus the app's own set when one is named."""
    paths = [path for path in THIRD_PARTY_NOTICE_DIRECTORY.glob("*") if path.is_file()]
    if app_name is not None:
        paths.extend(path for path in (THIRD_PARTY_NOTICE_DIRECTORY / app_name).rglob("*") if path.is_file())
    return tuple(
        sorted(
            THIRD_PARTY_NOTICE_ARCHIVE_PREFIX + path.relative_to(THIRD_PARTY_NOTICE_DIRECTORY).as_posix()
            for path in paths
        )
    )


