def run(cmd: list[str], *, cwd: Path | None = None, capture: bool = False, check: bool = True) -> subprocess.CompletedProcess[str]:
    print("+ " + " ".join(cmd))
    result = subprocess.run(
        cmd,
        cwd=str(cwd) if cwd else None,
        text=True,
        stdout=subprocess.PIPE if capture else None,
        stderr=subprocess.PIPE if capture else None,
        check=False,
    )
    if check and result.returncode != 0:
        if result.stdout:
            print(result.stdout, end="" if result.stdout.endswith("\n") else "\n")
        if result.stderr:
            print(result.stderr, file=sys.stderr, end="" if result.stderr.endswith("\n") else "\n")
        raise SystemExit(result.returncode)
    return result


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Build and publish TrayAppDotNET Win11 release assets.")
    parser.add_argument(
        "--phase",
        choices=[
            "build-app-profile",
            "build-installer-factory",
            "describe-app",
            "plan-publish",
            "publish-release",
        ],
        required=True,
        help="Build, plan, or publish TrayAppDotNET release packages, or describe one catalog app for CI.",
    )
    parser.add_argument(
        "--profile",
        choices=sorted(PROFILES),
        default="release",
        help="Profile to build in build-app-profile and build-installer-factory phases.",
    )
    parser.add_argument(
        "--profiles",
        default=",".join(PROFILES),
        help="Comma-separated profiles to collect and publish. Defaults to all profiles.",
    )
    parser.add_argument("--app-name", default="", help="App name to build in build-app-profile phase.")
    parser.add_argument(
        "--app-version",
        default="",
        help="App version to embed in build-app-profile phase. Defaults to the app buildnumber.txt value.",
    )
    parser.add_argument(
        "--apps",
        default=",".join(app.name for app in APPS),
        help="Comma-separated apps to collect and publish. Defaults to every app.",
    )
    parser.add_argument(
        "--force-apps",
        default="",
        help="Comma-separated apps to force-build in plan-publish phase.",
    )
    parser.add_argument(
        "--skip-apps",
        default="",
        help="Comma-separated apps to omit in plan-publish phase.",
    )
    parser.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY", "alchemyyy/TrayAppDotNET"))
    parser.add_argument(
        "--tray-version",
        default="",
        help=(
            "Aggregate TrayAppDotNET version. Defaults to latest published "
            f"TrayAppDotNET release + 1, with a floor of {INITIAL_RELEASE_VERSION}."
        ),
    )
    parser.add_argument(
        "--release-tag",
        default="",
        help=f"Release tag TrayAppDotNET_<number>, number >= {MINIMUM_RELEASE_TAG_VERSION}. Defaults to TrayAppDotNET_<version>.",
    )
    parser.add_argument("--target", default=os.environ.get("GITHUB_SHA", ""), help="Target commit for a new release.")
    parser.add_argument("--output-root", default=".artifacts/publish")
    parser.add_argument(
        "--installer-factory",
        default="",
        help=(
            "Path to a prebuilt installer factory executable. "
            "Defaults to building the factory in this job."
        ),
    )
    parser.add_argument("--input-root", default=".artifacts/publish/collected")
    parser.add_argument(
        "--force-rebuild",
        action="store_true",
        help="plan-publish phase: build every app even when its published package could be reused.",
    )
    parser.add_argument(
        "--reuse-latest",
        action="store_true",
        help="Download the app's latest published release asset instead of rebuilding it.",
    )
    return parser.parse_args()


def parse_profile_ids(value: str) -> list[str]:
    requested = [part.strip() for part in value.split(",") if part.strip()]
    if not requested:
        raise SystemExit("--profiles must include at least one profile")

    unknown = sorted(set(requested) - set(PROFILES))
    if unknown:
        raise SystemExit(f"Unknown profile(s): {', '.join(unknown)}")

    requested_set = set(requested)
    return [profile_id for profile_id in PROFILES if profile_id in requested_set]


def parse_app_names(value: str, *, argument_name: str, allow_empty: bool = False) -> list[App]:
    requested = [part.strip() for part in value.split(",") if part.strip()]
    if not requested and not allow_empty:
        raise SystemExit(f"{argument_name} must include at least one app")

    known_names = {app.name for app in APPS}
    unknown = sorted(set(requested) - known_names)
    if unknown:
        raise SystemExit(f"Unknown app(s) in {argument_name}: {', '.join(unknown)}")

    requested_names = set(requested)
    return [app for app in APPS if app.name in requested_names]


def read_buildnumber(path: Path) -> int:
    value = path.read_text(encoding="utf-8").strip()
    if not re.fullmatch(r"\d+", value):
        raise SystemExit(f"Expected numeric build number in {path}, got: {value!r}")
    return int(value)


def parse_app_version(value: str) -> int | None:
    normalized = value.strip()
    if not normalized:
        return None
    if not re.fullmatch(r"\d+", normalized):
        raise SystemExit(f"Expected --app-version to be a non-negative integer, got: {value!r}")
    return int(normalized)


def normalize_commit_hash(value: str) -> str:
    normalized = value.strip().lower()
    return normalized if re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", normalized) else ""


def app_commit_hash_from_versions_manifest(
    path: Path,
    app: App,
    profile: Profile,
    version: int,
) -> str:
    try:
        root = ET.parse(path).getroot()
    except (OSError, ET.ParseError):
        return ""

    for artifact in root.findall("./artifacts/artifact"):
        if artifact.get("kind") != "app":
            continue
        if artifact.get("profile") != profile.id:
            continue
        if artifact.get("appId") != app.name:
            continue
        if artifact.get("version") != str(version):
            continue
        return normalize_commit_hash(artifact.get("commitHash", ""))

    return ""


def latest_release(repo: str, *, missing_message: str = "No latest published release found; all apps will be built.") -> dict | None:
    result = run(["gh", "api", f"repos/{repo}/releases/latest"], capture=True, check=False)
    if result.returncode != 0:
        if missing_message:
            print(missing_message)
        return None
    return json.loads(result.stdout)


def published_releases(repo: str) -> list[dict]:
    page_size = 100
    page_number = 1
    releases: list[dict] = []

    while True:
        result = run(
            ["gh", "api", f"repos/{repo}/releases?per_page={page_size}&page={page_number}"],
            capture=True,
        )
        page = json.loads(result.stdout)
        if not isinstance(page, list):
            raise SystemExit("Expected the GitHub releases API to return a list.")

        releases.extend(
            release
            for release in page
            if not bool(release.get("draft")) and not bool(release.get("prerelease"))
        )
        if len(page) < page_size:
            break
        page_number += 1

    return releases


def release_version(release: dict | None) -> int | None:
    if not release:
        return None

    candidates: list[int] = []
    for value in (release.get("tag_name", ""), release.get("name", "")):
        match = re.search(r"\bTrayAppDotNET_(\d+)\b", str(value))
        if match:
            candidates.append(int(match.group(1)))

    aggregate_pattern = re.compile(r"^TrayAppDotNET_(\d+)\.zip$")
    for asset in release.get("assets", []):
        match = aggregate_pattern.fullmatch(str(asset.get("name", "")))
        if match:
            candidates.append(int(match.group(1)))

    return max(candidates) if candidates else None


def release_target_ref(release: dict | None) -> str:
    if not release:
        return ""
    # The tag is immutable while target_commitish is commonly a moving branch.
    for key in ("tag_name", "tagName", "target_commitish", "targetCommitish"):
        value = str(release.get(key, "")).strip()
        if value:
            return value
    return ""


def release_display_ref(release: dict | None) -> str:
    if not release:
        return "last release"
    for key in ("tag_name", "tagName", "name"):
        value = str(release.get(key, "")).strip()
        if value:
            return value
    return "last release"


def latest_reachable_release_tag(target: str) -> str:
    target_ref = target.strip() or "HEAD"
    result = run(
        [
            "git",
            "tag",
            "--merged",
            target_ref,
            "--list",
            "TrayAppDotNET_*",
        ],
        capture=True,
        check=False,
    )
    if result.returncode != 0:
        print(f"Warning: could not determine the latest release tag reachable from {target_ref}.")
        return ""

    candidates: list[tuple[int, str]] = []
    for tag in result.stdout.splitlines():
        normalized_tag = tag.strip()
        match = re.fullmatch(r"TrayAppDotNET_(\d+)", normalized_tag)
        if match:
            candidates.append((int(match.group(1)), normalized_tag))

    if not candidates:
        return ""
    return max(candidates)[1]


def commit_log(revision_range: str) -> list[CommitEntry] | None:
    """Lists the commits in a revision range with their changed paths, or None when Git fails."""
    result = run(
        [
            "git",
            "log",
            "--name-only",
            "--pretty=format:%x1e%H%x09%h%x09%s",
            revision_range,
        ],
        capture=True,
        check=False,
    )
    if result.returncode != 0:
        return None

    commits: list[CommitEntry] = []
    for record in result.stdout.split("\x1e"):
        record_lines = [line for line in record.splitlines() if line]
        if not record_lines:
            continue
        parts = record_lines[0].split("\t", 2)
        if len(parts) == 3:
            commits.append(
                CommitEntry(parts[0], parts[1], parts[2], tuple(record_lines[1:]))
            )
    return commits


def commits_since_release(previous_release: dict | None, target: str) -> list[CommitEntry]:
    target_ref = target.strip() or "HEAD"
    base_ref = release_target_ref(previous_release)
    revision_range = f"{base_ref}..{target_ref}" if base_ref else target_ref
    commits = commit_log(revision_range)
    if commits is None and base_ref:
        fallback_ref = str(previous_release.get("tag_name", "") if previous_release else "").strip()
        if fallback_ref and fallback_ref != base_ref:
            revision_range = f"{fallback_ref}..{target_ref}"
            commits = commit_log(revision_range)

    if commits is None:
        print(f"Warning: could not determine commits for {revision_range}.")
        return []
    return commits


def pull_requests_for_commits(repo: str, commits: list[CommitEntry]) -> list[PullRequestEntry]:
    pull_requests_by_number: dict[int, PullRequestEntry] = {}
    for commit in commits:
        result = run(
            [
                "gh",
                "api",
                "--header",
                "X-GitHub-Api-Version: 2022-11-28",
                f"repos/{repo}/commits/{commit.full_sha}/pulls",
            ],
            capture=True,
        )
        pull_request_data = json.loads(result.stdout)
        if not isinstance(pull_request_data, list):
            raise SystemExit(
                f"Expected the GitHub commit pull request API to return a list for {commit.full_sha}."
            )

        for pull_request in pull_request_data:
            if not pull_request.get("merged_at"):
                continue

            number = int(pull_request["number"])
            user = pull_request.get("user") or {}
            title = " ".join(str(pull_request.get("title", "")).split())
            pull_requests_by_number[number] = PullRequestEntry(
                number=number,
                title=title or f"Pull request #{number}",
                author_username=str(user.get("login", "ghost")),
                url=str(pull_request["html_url"]),
            )

    return [pull_requests_by_number[number] for number in sorted(pull_requests_by_number)]


def default_tray_version(latest: dict | None) -> int:
    latest_version = release_version(latest)
    if latest_version is None:
        return INITIAL_RELEASE_VERSION
    return max(latest_version + 1, INITIAL_RELEASE_VERSION)


def release_tag_version(release_tag: str) -> int:
    match = RELEASE_TAG_PATTERN.fullmatch(release_tag)
    if match is None or int(match.group(1)) < MINIMUM_RELEASE_TAG_VERSION:
        raise SystemExit(
            f"Invalid release tag {release_tag!r}: expected TrayAppDotNET_<number> with number >= "
            f"{MINIMUM_RELEASE_TAG_VERSION}, which the version endpoint updater requires."
        )
    return int(match.group(1))


def validate_release_tag(release_tag: str, tray_version: int) -> str:
    # The endpoint accepts a release only when its tag is TrayAppDotNET_<versions@version>.
    if release_tag_version(release_tag) != tray_version:
        raise SystemExit(
            f"Invalid release tag {release_tag!r}: the version endpoint requires TrayAppDotNET_{tray_version} "
            f"for TrayAppDotNET version {tray_version}."
        )
    return release_tag


def app_asset_name(app: App, version: int, profile: Profile) -> str:
    if profile.legacy_names:
        return f"{app.name}_{version}.zip"
    token = profile_asset_token(profile)
    return f"{app.name}_{version}_{token}.zip"


def aggregate_asset_name(tray_version: int, profile: Profile) -> str:
    if profile.legacy_names:
        return f"TrayAppDotNET_{tray_version}.zip"
    token = profile_asset_token(profile)
    return f"TrayAppDotNET_{tray_version}_{token}.zip"


def profile_asset_token(profile: Profile) -> str:
    return profile.id.replace("-", "").title()


def app_asset_pattern(app: App, profile: Profile) -> re.Pattern[str]:
    escaped_name = re.escape(app.name)
    if profile.legacy_names:
        return re.compile(rf"^{escaped_name}_(\d+)\.zip$")
    escaped_token = re.escape(profile_asset_token(profile))
    return re.compile(rf"^{escaped_name}_(\d+)_{escaped_token}\.zip$")


def aggregate_asset_pattern(profile: Profile) -> re.Pattern[str]:
    if profile.legacy_names:
        return re.compile(r"^TrayAppDotNET_(\d+)\.zip$")
    escaped_token = re.escape(profile_asset_token(profile))
    return re.compile(rf"^TrayAppDotNET_(\d+)_{escaped_token}\.zip$")


def latest_published_tray_release(releases: list[dict], profile: Profile) -> dict | None:
    pattern = aggregate_asset_pattern(profile)
    for release in releases:
        release_tag = str(release.get("tag_name", "")).strip()
        if not release_tag:
            continue

        for asset in release.get("assets", []):
            if pattern.fullmatch(str(asset.get("name", ""))):
                return release

    return None


def latest_published_app_asset(
    releases: list[dict],
    app: App,
    profile: Profile,
) -> PublishedAppAsset | None:
    pattern = app_asset_pattern(app, profile)
    for release in releases:
        release_tag = str(release.get("tag_name", "")).strip()
        if not release_tag:
            continue

        for asset in release.get("assets", []):
            file_name = str(asset.get("name", ""))
            match = pattern.fullmatch(file_name)
            if not match:
                continue
            return PublishedAppAsset(
                release_tag=release_tag,
                version=int(match.group(1)),
                file_name=file_name,
                digest=str(asset.get("digest", "")).strip(),
            )

    return None


def is_pdb_name(name: str) -> bool:
    return name.lower().endswith(".pdb")


def remove_pdb_files(root: Path) -> int:
    count = 0
    for path in sorted(root.rglob("*")):
        if path.is_file() and path.suffix.lower() == ".pdb":
            path.unlink()
            count += 1
    return count


def native_aot_prune_lists(targets_path: Path = PARENT_TARGETS_PATH) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """The sidecar files and folders PublishAfterBuild prunes from a Native AOT publish, read from Parent.targets."""
    root = ET.parse(targets_path).getroot()

    def items(name: str) -> tuple[str, ...]:
        return tuple(
            part.strip()
            for element in root.iter(name)
            for part in element.get("Include", "").split(";")
            if part.strip()
        )

    files = items("TrayAppDotNETPublishPruneFile")
    directories = items("TrayAppDotNETPublishPruneDirectory")
    if not files or not directories:
        raise SystemExit(f"Missing the Native AOT publish prune lists in {targets_path}")
    return files, directories


def remove_native_aot_sidecars(publish_dir: Path) -> None:
    files, directories = native_aot_prune_lists()
    for name in files:
        path = publish_dir / name
        if path.exists():
            path.unlink()

    for name in directories:
        path = publish_dir / name
        if path.exists():
            shutil.rmtree(path)


def app_build_output_dir(app: App) -> Path:
    return (REPO_ROOT / app.project).parent.parent / "bin" / "Release"


def is_root_app_install_name(name: str) -> bool:
    return name.replace("\\", "/").lower() == APP_INSTALL_ARCHIVE_NAME


def write_unique_zip_entry(archive: ZipFile, seen: dict[str, str], name: str, content: bytes) -> None:
    digest = hashlib.sha256(content).hexdigest()
    existing_digest = seen.get(name)
    if existing_digest == digest:
        return
    # Apps share only byte-identical files (native DLLs, legal texts), so differing content at one
    # path means one app would silently run or ship the other's copy, whatever the extension.
    if existing_digest is not None:
        raise SystemExit(
            f"Zip path collision for {name}: two inputs supply different content. "
            "Refusing to keep either copy silently."
        )
    seen[name] = digest
    archive.writestr(name, content)


def install_all_script(app_names: list[str]) -> bytes:
    calls = "\n".join(f'call :InstallApp "{app_name}.exe"' for app_name in app_names)
    script = INSTALL_ALL_SCRIPT_TEMPLATE.replace(INSTALL_ALL_APP_CALLS_PLACEHOLDER, calls)
    return script.replace("\n", "\r\n").encode("ascii")


def write_install_all_script(archive: ZipFile, seen: dict[str, str], app_names: list[str]) -> None:
    write_unique_zip_entry(
        archive,
        seen,
        INSTALL_ALL_ARCHIVE_NAME,
        install_all_script(app_names),
    )


def app_install_script(app_name: str) -> bytes:
    script = APP_INSTALL_SCRIPT_TEMPLATE.replace(APP_INSTALL_SCRIPT_EXE_PLACEHOLDER, f"{app_name}.exe")
    return script.replace("\n", "\r\n").encode("ascii")


def app_install_entries(app_name: str) -> dict[str, bytes]:
    return {APP_INSTALL_ARCHIVE_NAME: app_install_script(app_name)}


def aggregate_app_install_archive_name(app_name: str) -> str:
    return f"install-{app_name}.bat"


def write_aggregate_app_install_script(archive: ZipFile, seen: dict[str, str], app_name: str) -> None:
    write_unique_zip_entry(
        archive,
        seen,
        aggregate_app_install_archive_name(app_name),
        app_install_script(app_name),
    )


def zip_directory(
    source_dir: Path,
    zip_path: Path,
    *,
    extra_entries: dict[str, bytes] | None = None,
) -> Path | None:
    zip_path.parent.mkdir(parents=True, exist_ok=True)
    if zip_path.exists():
        zip_path.unlink()

    files = []
    for path in sorted(source_dir.rglob("*")):
        if not path.is_file():
            continue
        if path.suffix.lower() == ".pdb":
            raise SystemExit(f"Refusing to package PDB file: {path}")
        files.append(path)

    if not files and not extra_entries:
        return None

    seen: dict[str, str] = {}
    with ZipFile(zip_path, "w", ZIP_DEFLATED) as archive:
        for name, content in (extra_entries or {}).items():
            write_unique_zip_entry(archive, seen, name, content)
        for path in files:
            write_unique_zip_entry(archive, seen, path.relative_to(source_dir).as_posix(), path.read_bytes())

    return zip_path


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def publish_command(
    app: App,
    publish_dir: Path,
    profile: Profile,
    version: int,
    commit_hash: str,
) -> list[str]:
    cmd = [
        "dotnet",
        "publish",
        app.project,
        "--no-restore",
        "--configuration",
        PUBLISH_CONFIGURATION,
        "--runtime",
        "win-x64",
        "--self-contained",
        str(profile.self_contained).lower(),
        "--output",
        str(publish_dir),
        "-m:1",
        f"-p:PublishAot={str(profile.publish_aot).lower()}",
        "-p:PublishSingleFile=false",
        f"-p:SelfContained={str(profile.self_contained).lower()}",
        "-p:IncludeNativeLibrariesForSelfExtract=false",
        "-p:IncludeAllContentForSelfExtract=false",
        "-p:DebugType=none",
        "-p:DebugSymbols=false",
        "-p:UseAppHost=true",
        "-p:EnableWindowsTargeting=true",
        "-p:SkipPublishAfterBuild=true",
        "-p:SkipKillRunningInstance=true",
        "-p:ContinuousIntegrationBuild=true",
        f"-p:BuildNumber={version}",
    ]
    if commit_hash:
        cmd.append(f"-p:TrayAppDotNETCommitHash={commit_hash}")

    return cmd


def generator_restore_commands() -> list[list[str]]:
    commands: list[list[str]] = []
    for generator_project in GENERATOR_PROJECTS:
        commands.append(
            [
                "dotnet",
                "restore",
                generator_project,
                f"-p:Configuration={PUBLISH_CONFIGURATION}",
            ]
        )
    return commands


def restore_command(app: App, profile: Profile) -> list[str]:
    cmd = [
        "dotnet",
        "restore",
        app.project,
        "--runtime",
        "win-x64",
        f"-p:Configuration={PUBLISH_CONFIGURATION}",
        f"-p:SelfContained={str(profile.self_contained).lower()}",
        "-p:EnableWindowsTargeting=true",
        f"-p:PublishAot={str(profile.publish_aot).lower()}",
    ]

    return cmd


def installer_asset_name(name: str, version: int) -> str:
    # Carries the version of the package inside, so an app installer matches its "<App>_<version>.zip"
    # and the suite installer matches the "TrayAppDotNET_<version>.zip" aggregate.
    return f"{INSTALLER_ASSET_PREFIX}{name}_{version}.exe"


def installer_restore_command() -> list[str]:
    # The installer targets .NET Framework 4.8, which has no runtime identifier to restore for.
    return [
        "dotnet",
        "restore",
        INSTALLER_PROJECT,
        f"-p:Configuration={PUBLISH_CONFIGURATION}",
    ]


def installer_factory_publish_command(publish_dir: Path, commit_hash: str) -> list[str]:
    # The factory carries no payload and no icon override, so one publish serves every installer.
    # Payloads are supplied later, per stamp, on the factory command line. The .NET Framework and
    # its renderer ship inside Windows, so a plain publish produces the single factory executable
    # without a runtime identifier, a self-contained runtime or ahead-of-time compilation.
    cmd = [
        "dotnet",
        "publish",
        INSTALLER_PROJECT,
        "--no-restore",
        "--configuration",
        PUBLISH_CONFIGURATION,
        "--output",
        str(publish_dir),
        "-m:1",
        "-p:DebugType=none",
        "-p:DebugSymbols=false",
        "-p:SkipKillRunningInstance=true",
        "-p:ContinuousIntegrationBuild=true",
    ]
    if commit_hash:
        cmd.append(f"-p:TrayAppDotNETCommitHash={commit_hash}")

    return cmd


def validate_legal_archive_entries(
    entry_names: list[str],
    archive_description: str,
    required_notice_names: tuple[str, ...],
) -> None:
    normalized_names = {name.replace("\\", "/") for name in entry_names}
    missing_names = [
        required_name
        for required_name in REQUIRED_LEGAL_ARCHIVE_FILES
        if required_name not in normalized_names
    ]
    if missing_names:
        raise SystemExit(
            f"{archive_description} is missing required legal file(s): "
            f"{', '.join(missing_names)}"
        )

    if not required_notice_names:
        raise SystemExit(
            f"Repository does not contain any files under "
            f"{THIRD_PARTY_NOTICE_DIRECTORY}"
        )
    missing_third_party_license_names = [
        required_name
        for required_name in required_notice_names
        if required_name not in normalized_names
    ]
    if missing_third_party_license_names:
        raise SystemExit(
            f"{archive_description} is missing required third-party license file(s): "
            f"{', '.join(missing_third_party_license_names)}"
        )

    repository_notice_prefix = f"{THIRD_PARTY_NOTICE_ARCHIVE_PREFIX}{REPOSITORY_NOTICE_DIRECTORY_NAME}/"
    repository_only_names = sorted(name for name in normalized_names if name.startswith(repository_notice_prefix))
    if repository_only_names:
        raise SystemExit(
            f"{archive_description} carries repository-only notice(s): {', '.join(repository_only_names)}"
        )


def validate_legal_directory(app: App, publish_dir: Path) -> None:
    entry_names = [
        path.relative_to(publish_dir).as_posix()
        for path in publish_dir.rglob("*")
        if path.is_file()
    ]
    validate_legal_archive_entries(
        entry_names,
        f"Publish directory {publish_dir}",
        third_party_notice_archive_files(app.name),
    )


def shared_native_dll_names(contract_path: Path = INSTALL_CONTRACT_PATH) -> tuple[str, ...]:
    if not contract_path.is_file():
        raise SystemExit(f"Missing install contract with the shared native DLL list: {contract_path}")
    match = SHARED_NATIVE_DLL_NAMES_PATTERN.search(contract_path.read_text(encoding="utf-8"))
    if match is None:
        raise SystemExit(f"Install contract {contract_path} does not define SharedNativeDllNames.")
    names = tuple(re.findall(r'"([^"]+)"', match.group(1)))
    if not names:
        raise SystemExit(f"Install contract {contract_path} has an empty SharedNativeDllNames list.")
    return names


def validate_loose_native_aot_dlls(app: App, publish_dir: Path) -> None:
    missing_names = [
        name
        for name in shared_native_dll_names()
        if not (publish_dir / name).is_file()
    ]
    if missing_names:
        raise SystemExit(
            f"{app.name} Native AOT publish is missing required loose native DLL(s): "
            f"{', '.join(missing_names)}. Refusing to package an incomplete publish."
        )


def validate_publish_dir(app: App, publish_dir: Path, profile: Profile) -> None:
    expected_exe = publish_dir / f"{app.name}.exe"
    app_dll = publish_dir / f"{app.name}.dll"

    validate_legal_directory(app, publish_dir)

    if not expected_exe.exists():
        raise SystemExit(
            f"{app.name} {profile.display_name} publish did not produce {expected_exe.name}. "
            "Refusing to package a failed publish."
        )

    if profile.publish_aot:
        if app_dll.exists():
            raise SystemExit(
                f"{app.name} Native AOT publish produced {app_dll.name}. "
                "Refusing to package a managed publish as Native AOT."
            )
        validate_loose_native_aot_dlls(app, publish_dir)
        return

    if not app_dll.exists():
        raise SystemExit(
            f"{app.name} {profile.display_name} publish did not produce {app_dll.name}. "
            "Refusing to package a single-file or incomplete publish."
        )

    bundled_runtime = [name for name in ("coreclr.dll", "hostfxr.dll", "hostpolicy.dll") if (publish_dir / name).exists()]
    if bundled_runtime and not profile.self_contained:
        joined = ", ".join(bundled_runtime)
        raise SystemExit(
            f"{app.name} Release publish contains bundled runtime files ({joined}). "
            "Refusing to package a self-contained publish."
        )
    if profile.self_contained and not bundled_runtime:
        raise SystemExit(
            f"{app.name} {profile.display_name} publish did not contain bundled runtime files. "
            "Refusing to package a framework-dependent publish as self-contained."
        )


def build_app(
    app: App,
    version: int,
    output_root: Path,
    profile: Profile,
    commit_hash: str,
) -> AppPackage:
    publish_dir = output_root / profile.id / "publish" / app.name
    package_dir = output_root / profile.id / "packages"
    zip_path = package_dir / app_asset_name(app, version, profile)

    if publish_dir.exists():
        shutil.rmtree(publish_dir)
    publish_dir.mkdir(parents=True, exist_ok=True)

    # Publish runs with --no-restore and configuration-specific project extension paths.
    # Keep generator restores explicit because AOT restore conditions can exclude analyzer
    # ProjectReferences from the app restore graph.
    for generator_restore_command in generator_restore_commands():
        run(generator_restore_command)
    run(restore_command(app, profile))
    run(publish_command(app, publish_dir, profile, version, commit_hash))
    if profile.publish_aot:
        remove_native_aot_sidecars(publish_dir)
    removed_publish_pdbs = remove_pdb_files(publish_dir)
    build_output_dir = app_build_output_dir(app)
    removed_build_pdbs = remove_pdb_files(build_output_dir) if build_output_dir.exists() else 0
    removed_pdbs = removed_publish_pdbs + removed_build_pdbs
    if removed_pdbs:
        print(
            f"{app.name} {profile.display_name}: removed {removed_pdbs} PDB file(s) "
            f"({removed_publish_pdbs} publish, {removed_build_pdbs} build output)."
        )
    validate_publish_dir(app, publish_dir, profile)
    if zip_directory(publish_dir, zip_path, extra_entries=app_install_entries(app.name)) is None:
        raise SystemExit(f"{app.name} {profile.display_name} publish produced no runtime files.")
    return AppPackage(app, profile, version, zip_path, profile.build_source, commit_hash)


def validate_installer_publish_dir(
    name: str, publish_dir: Path, assembly_name: str
) -> Path:
    expected_exe = publish_dir / f"{assembly_name}.exe"
    if not expected_exe.is_file():
        raise SystemExit(
            f"{name} installer publish did not produce {expected_exe.name}. "
            "Refusing to package a failed installer publish."
        )

    leftover_dll_names = sorted(
        path.relative_to(publish_dir).as_posix()
        for path in publish_dir.rglob("*")
        if path.is_file() and path.suffix.lower() == ".dll"
    )
    if leftover_dll_names:
        raise SystemExit(
            f"{name} installer publish left DLL file(s) next to {expected_exe.name}: "
            f"{', '.join(leftover_dll_names)}. Refusing to package a multi-file installer."
        )
    return expected_exe


def build_installer_factory(
    output_root: Path, profile: Profile, commit_hash: str
) -> Path:
    """Publishes the payload-free installer factory once and returns its executable."""
    publish_dir = output_root / profile.id / "installer" / "factory" / "publish"
    if publish_dir.exists():
        shutil.rmtree(publish_dir)
    publish_dir.mkdir(parents=True, exist_ok=True)

    # The installer project references no generator, so its own restore is all the --no-restore
    # publish needs. Only the application path still restores the generators.
    run(installer_restore_command())
    run(installer_factory_publish_command(publish_dir, commit_hash))
    removed_pdbs = remove_pdb_files(publish_dir)
    if removed_pdbs:
        print(f"Installer factory: removed {removed_pdbs} PDB file(s).")
    return validate_installer_publish_dir(
        INSTALLER_FACTORY_ASSEMBLY_NAME,
        publish_dir,
        INSTALLER_FACTORY_ASSEMBLY_NAME,
    )


def stamp_installer(
    factory_path: Path,
    name: str,
    payload_zip_paths: list[Path],
    output_path: Path,
) -> Path:
    """Runs the installer factory once to stamp one finished installer executable."""
    if not factory_path.is_file():
        raise SystemExit(f"{name} installer factory not found: {factory_path}")
    if not payload_zip_paths:
        raise SystemExit(f"{name} installer requires at least one payload zip.")
    missing_payloads = [str(path) for path in payload_zip_paths if not path.is_file()]
    if missing_payloads:
        raise SystemExit(
            f"{name} installer payload zip(s) not found: {', '.join(missing_payloads)}"
        )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    # A stale installer left by an earlier run would defeat the checks below.
    if output_path.exists():
        output_path.unlink()
    # The factory derives each app name, the version and the icon from the
    # "<AppName>_<version>.zip" payload file names, so payload paths are passed unchanged.
    command = [
        str(factory_path.resolve()),
        "--make-installer",
        "--output",
        str(output_path.resolve()),
    ]
    for payload_zip_path in payload_zip_paths:
        command.extend(["--payload", str(payload_zip_path.resolve())])
    run(command)

    if not output_path.is_file():
        raise SystemExit(
            f"{name} installer factory reported success but did not write {output_path}."
        )
    # No size comparison can prove the payload is there any more: the payloads are LZMA-recompressed,
    # so the stamped installer is routinely smaller than the input zips, and stamping rewrites the icon
    # resource group, so the factory image is not a lower bound either. Only the floor below and the
    # structural verification that follows it are sound.
    payload_size = sum(path.stat().st_size for path in payload_zip_paths)
    installer_size = output_path.stat().st_size
    if installer_size <= INSTALLER_MINIMUM_SIZE_BYTES:
        raise SystemExit(
            f"{name} installer is only {installer_size} bytes "
            f"(minimum {INSTALLER_MINIMUM_SIZE_BYTES} bytes). "
            "Refusing to publish a truncated installer."
        )

    # The factory reopens the image it just wrote and checks the payload directory hash, that every
    # payload decompresses and that every recorded SHA-256 matches.
    verify_result = run(
        [
            str(factory_path.resolve()),
            "--verify-installer",
            "--image",
            str(output_path.resolve()),
        ],
        capture=True,
        check=False,
    )
    if verify_result.stdout:
        print(verify_result.stdout, end="" if verify_result.stdout.endswith("\n") else "\n")
    if verify_result.returncode != 0:
        if verify_result.stderr:
            print(verify_result.stderr, file=sys.stderr, end="" if verify_result.stderr.endswith("\n") else "\n")
        raise SystemExit(
            f"{name} installer failed payload verification "
            f"(exit code {verify_result.returncode}). "
            "Refusing to publish an installer without a verified payload."
        )

    compressed_percent = installer_size * 100 / payload_size if payload_size else 0.0
    print(
        f"{name} installer: {payload_size} payload byte(s) stamped into "
        f"{installer_size} installer byte(s) ({compressed_percent:.1f}%)."
    )
    return output_path


def resolve_installer_factory(
    installer_factory: str,
    output_root: Path,
    profile: Profile,
    commit_hash: str,
) -> Path:
    """Uses the supplied installer factory when it exists, otherwise builds one."""
    requested_path = installer_factory.strip()
    if requested_path:
        factory_path = Path(requested_path)
        if factory_path.is_file():
            print(f"Using the supplied installer factory: {factory_path}")
            return factory_path
        print(
            f"Supplied installer factory not found: {factory_path}; "
            "building the installer factory in this job."
        )
    else:
        print("No installer factory was supplied; building one in this job.")
    return build_installer_factory(output_root, profile, commit_hash)


def published_app_commit_hash(
    repo: str,
    asset: PublishedAppAsset,
    app: App,
    profile: Profile,
    package_dir: Path,
) -> str:
    versions_path = package_dir / "published-versions.xml"
    if versions_path.exists():
        versions_path.unlink()

    result = run(
        [
            "gh",
            "release",
            "download",
            asset.release_tag,
            "--repo",
            repo,
            "--pattern",
            "versions.xml",
            "--output",
            str(versions_path),
        ],
        capture=True,
        check=False,
    )
    commit_hash = ""
    if result.returncode == 0 and versions_path.exists():
        commit_hash = app_commit_hash_from_versions_manifest(
            versions_path,
            app,
            profile,
            asset.version,
        )
    if versions_path.exists():
        versions_path.unlink()

    return commit_hash or try_resolve_git_commit(asset.release_tag)


def published_app_build_commit(
    repo: str,
    asset: PublishedAppAsset,
    app: App,
    profile: Profile,
) -> str:
    """Resolves the commit a published app package was built from, or returns an empty string."""
    with tempfile.TemporaryDirectory() as scratch_directory:
        recorded_commit = published_app_commit_hash(
            repo, asset, app, profile, Path(scratch_directory)
        )
    # A carried-forward package records the commit it was built from in versions.xml,
    # while its release tag points at the newer release that re-attached it
    build_commit = try_resolve_git_commit(recorded_commit) if recorded_commit else ""
    return build_commit or try_resolve_git_commit(asset.release_tag)


def download_published_app(
    repo: str,
    output_root: Path,
    profile: Profile,
    app: App,
) -> AppPackage:
    asset = latest_published_app_asset(published_releases(repo), app, profile)
    if asset is None:
        raise SystemExit(f"No published {profile.display_name} asset was found for {app.name}.")

    package_dir = output_root / profile.id / "packages"
    package_dir.mkdir(parents=True, exist_ok=True)
    zip_path = package_dir / asset.file_name
    if zip_path.exists():
        zip_path.unlink()

    run(
        [
            "gh",
            "release",
            "download",
            asset.release_tag,
            "--repo",
            repo,
            "--pattern",
            asset.file_name,
            "--output",
            str(zip_path),
        ]
    )

    try:
        with ZipFile(zip_path, "r") as archive:
            invalid_entry = archive.testzip()
            # A published asset was checked against its app's full notice set when it was built. Packages from before
            # the per-app notice folders carried every notice flat, so a reused asset only has to carry the shared set.
            validate_legal_archive_entries(
                archive.namelist(),
                f"Downloaded app asset {asset.file_name}",
                SHARED_THIRD_PARTY_LICENSE_ARCHIVE_FILES,
            )
    except (OSError, BadZipFile) as error:
        raise SystemExit(f"Downloaded app asset is not a readable zip: {zip_path}: {error}") from error
    if invalid_entry is not None:
        raise SystemExit(f"Downloaded app asset contains an invalid entry: {zip_path}: {invalid_entry}")

    if not asset.digest.startswith("sha256:"):
        raise SystemExit(
            f"Published app asset {asset.file_name} in {asset.release_tag} has no GitHub sha256 digest; "
            "refusing to carry forward an unverifiable package."
        )
    expected_digest = asset.digest.removeprefix("sha256:").lower()
    actual_digest = sha256_file(zip_path)
    if actual_digest.lower() != expected_digest:
        raise SystemExit(
            f"Downloaded app asset checksum mismatch for {asset.file_name}: "
            f"expected {expected_digest}, got {actual_digest}"
        )

    print(
        f"{app.name} {profile.display_name}: reused version {asset.version} "
        f"from published release {asset.release_tag}."
    )
    commit_hash = published_app_commit_hash(repo, asset, app, profile, package_dir)
    return AppPackage(
        app,
        profile,
        asset.version,
        zip_path,
        f"{REUSED_PACKAGE_SOURCE_PREFIX}{asset.release_tag}",
        commit_hash,
    )


def app_by_name(app_name: str) -> App:
    for app in APPS:
        if app.name == app_name:
            return app
    valid = ", ".join(app.name for app in APPS)
    raise SystemExit(f"Unknown app name: {app_name!r}. Expected one of: {valid}")


def selected_app_package(
    repo: str,
    output_root: Path,
    reuse_latest: bool,
    profile: Profile,
    app: App,
    app_version: int | None,
    commit_hash: str,
) -> AppPackage:
    if reuse_latest:
        return download_published_app(repo, output_root, profile, app)

    current_version = app_version if app_version is not None else read_buildnumber(Path(app.buildnumber))
    print(f"{app.name} {profile.display_name}: building current {current_version}.")
    return build_app(app, current_version, output_root, profile, commit_hash)


def app_manifest_data(package: AppPackage, installer_path: Path) -> dict:
    app_data = {
        "appId": package.app.name,
        "version": package.version,
        "fileName": package.zip_path.name,
        "sha256": sha256_file(package.zip_path),
        "size": package.zip_path.stat().st_size,
        "source": package.source,
        "commitHash": package.commit_hash,
        "installerFileName": installer_path.name,
        "installerSha256": sha256_file(installer_path),
        "installerSize": installer_path.stat().st_size,
    }

    return {
        "profile": package.profile.id,
        "displayName": package.profile.display_name,
        "runtime": "win-x64",
        "app": app_data,
    }


def build_app_profile(args: argparse.Namespace) -> int:
    if not args.app_name.strip():
        raise SystemExit("--app-name is required for build-app-profile phase.")

    profile = PROFILES[args.profile]
    app = app_by_name(args.app_name.strip())
    output_root = Path(args.output_root)
    package_dir = output_root / profile.id / "packages"
    package_dir.mkdir(parents=True, exist_ok=True)
    app_version = parse_app_version(args.app_version)
    commit_hash = try_resolve_git_commit("HEAD")

    package = selected_app_package(
        args.repo,
        output_root,
        args.reuse_latest,
        profile,
        app,
        app_version,
        commit_hash,
    )
    # The installer is always stamped from the package zip at the current commit, even when the
    # zip itself was reused from a published release.
    factory_path = resolve_installer_factory(
        args.installer_factory,
        output_root,
        profile,
        commit_hash,
    )
    # The package version, not the requested one: a reused package keeps the version it was published under
    installer_path = stamp_installer(
        factory_path,
        app.name,
        [package.zip_path],
        package_dir / installer_asset_name(app.name, package.version),
    )
    manifest_path = package_dir / f"app-{profile.id}-{app.name}.json"
    manifest_path.write_text(
        json.dumps(app_manifest_data(package, installer_path), indent=2) + "\n",
        encoding="utf-8",
    )

    print(f"Built {profile.display_name} package:")
    print(f"- {package.zip_path}")
    print(f"- {installer_path}")
    print(f"- {manifest_path}")
    return 0


def build_installer_factory_profile(args: argparse.Namespace) -> int:
    profile = PROFILES[args.profile]
    output_root = Path(args.output_root)
    commit_hash = try_resolve_git_commit("HEAD")

    published_factory_path = build_installer_factory(output_root, profile, commit_hash)
    # The workflow uploads the factory from the output root, so keep a stable copy there.
    factory_path = output_root / INSTALLER_FACTORY_EXECUTABLE_NAME
    if factory_path.resolve() != published_factory_path.resolve():
        shutil.copy2(published_factory_path, factory_path)

    print("Built installer factory:")
    print(f"- {published_factory_path}")
    print(f"- {factory_path}")
    return 0


def set_github_output(name: str, value: str) -> None:
    output_path = os.environ.get("GITHUB_OUTPUT")
    if output_path:
        with Path(output_path).open("a", encoding="utf-8") as output:
            output.write(f"{name}={value}\n")
    print(f"{name}={value}")


def try_resolve_git_commit(reference: str) -> str:
    result = run(
        ["git", "rev-parse", "--verify", f"{reference}^{{commit}}"],
        capture=True,
        check=False,
    )
    commit_hash = normalize_commit_hash(result.stdout)
    if result.returncode != 0 or not commit_hash:
        print(f"Warning: could not resolve Git commit hash for {reference}.")
        return ""
    return commit_hash


def resolve_git_commit(reference: str) -> str:
    commit_hash = try_resolve_git_commit(reference)
    if not commit_hash:
        raise SystemExit(f"Failed to resolve Git reference to a commit: {reference}")
    return commit_hash


def require_ancestor(base_commit: str, target_commit: str, description: str) -> None:
    result = run(
        ["git", "merge-base", "--is-ancestor", base_commit, target_commit],
        check=False,
    )
    if result.returncode != 0:
        raise SystemExit(f"{description} is not an ancestor of target {target_commit}.")


def has_changes_since(
    base_commit: str,
    target_commit: str,
    included_paths: list[str],
    excluded_paths: list[str],
) -> bool:
    pathspecs = list(included_paths)
    for excluded_path in excluded_paths:
        pathspecs.append(f":(exclude){excluded_path}")

    result = run(
        [
            "git",
            "rev-list",
            "--max-count=1",
            f"{base_commit}..{target_commit}",
            "--",
            *pathspecs,
        ],
        capture=True,
    )
    return bool(result.stdout.strip())


def plan_publish(args: argparse.Namespace) -> int:
    profile = PROFILES["release"]
    forced_apps = {
        app.name
        for app in parse_app_names(
            args.force_apps,
            argument_name="--force-apps",
            allow_empty=True,
        )
    }
    skipped_apps = {
        app.name
        for app in parse_app_names(
            args.skip_apps,
            argument_name="--skip-apps",
            allow_empty=True,
        )
    }
    if all(app.name in skipped_apps for app in APPS):
        raise SystemExit("Publish cannot skip every app.")

    target_reference = args.target.strip() or "HEAD"
    target_commit = resolve_git_commit(target_reference)
    releases = published_releases(args.repo)
    release_matrix: list[dict] = []

    def plan_app(app: App, version: int, reuse: bool) -> None:
        release_matrix.append(
            {
                "name": app.name,
                "slug": app.slug,
                "displayName": app.display_name,
                "version": version,
                "reuse": reuse,
            }
        )

    previous_tray_release = latest_published_tray_release(releases, profile)
    previous_tray_tag = ""
    tray_base_commit = ""
    shared_inputs_changed = previous_tray_release is None
    shared_change_reason = "no prior aggregate TrayAppDotNET release exists"
    if previous_tray_release is None:
        print("Shared release inputs: no prior aggregate release exists; building every included app.")
    else:
        previous_tray_tag = str(previous_tray_release["tag_name"]).strip()
        tray_base_commit = resolve_git_commit(previous_tray_tag)
        require_ancestor(
            tray_base_commit, target_commit, f"Release tag '{previous_tray_tag}'"
        )
        shared_inputs_changed = has_changes_since(
            tray_base_commit,
            target_commit,
            SHARED_RELEASE_INPUT_PATHS,
            [],
        )
        shared_change_reason = f"shared release input changes found since {previous_tray_tag}"
        if shared_inputs_changed:
            print(
                f"Shared release inputs: changes found since {previous_tray_tag}; "
                "building every included app."
            )
        else:
            print(f"Shared release inputs: no changes since {previous_tray_tag}.")

    for app in APPS:
        previous_asset = latest_published_app_asset(releases, app, profile)
        if app.name in skipped_apps:
            if previous_asset is None:
                print(
                    f"{app.name}: skipped by workflow input; no published package exists to carry forward."
                )
                continue

            # A skipped app keeps shipping the package it already has, so the release stays complete
            print(
                f"{app.name}: skipped by workflow input; carrying forward {previous_asset.file_name} "
                f"from {previous_asset.release_tag}."
            )
            plan_app(app, previous_asset.version, reuse=True)
            continue

        force_rebuild = args.force_rebuild or app.name in forced_apps

        if previous_asset is None:
            tracked_version = read_buildnumber(Path(app.buildnumber))
            planned_version = max(tracked_version, INITIAL_RELEASE_VERSION)
            print(
                f"{app.name}: no prior app release exists; building version {planned_version}."
            )
            plan_app(app, planned_version, reuse=False)
            continue

        has_relevant_changes = shared_inputs_changed
        change_reason = shared_change_reason
        unchanged_scope = "app"
        if not shared_inputs_changed:
            # A skip carries a package into releases newer than the commit it was built from,
            # so changes count from that build commit rather than from the release tag
            base_commit = published_app_build_commit(
                args.repo, previous_asset, app, profile
            )
            if not base_commit:
                raise SystemExit(
                    f"Failed to resolve the commit {previous_asset.file_name} was built from."
                )
            require_ancestor(
                base_commit,
                target_commit,
                f"The {previous_asset.file_name} build commit {base_commit}",
            )

            included_paths = [app.name]
            if base_commit != tray_base_commit:
                included_paths.extend(SHARED_RELEASE_INPUT_PATHS)
                unchanged_scope = "app or shared release input"

            has_relevant_changes = has_changes_since(
                base_commit,
                target_commit,
                included_paths,
                [app.buildnumber],
            )
            change_reason = (
                f"relevant changes found since {previous_asset.file_name} was built"
            )

        if not has_relevant_changes and not force_rebuild:
            print(
                f"{app.name}: no {unchanged_scope} changes since {previous_asset.file_name} was built; "
                f"reusing it from {previous_asset.release_tag}."
            )
            plan_app(app, previous_asset.version, reuse=True)
            continue

        tracked_version = read_buildnumber(Path(app.buildnumber))
        if has_relevant_changes:
            planned_version = max(tracked_version, previous_asset.version + 1)
            print(
                f"{app.name}: planning version {planned_version} from published version "
                f"{previous_asset.version}; {change_reason}."
            )
        else:
            planned_version = max(tracked_version, previous_asset.version)
            print(f"{app.name}: force rebuild selected at version {planned_version}.")

        plan_app(app, planned_version, reuse=False)

    set_github_output("source_sha", target_commit)
    # One entry per app the release carries, built or reused; the publish workflow runs app-release.yml
    # once per entry. Skipped apps without a published package are left out of the release entirely.
    set_github_output("release_matrix", json.dumps(release_matrix, separators=(",", ":")))
    set_github_output("included_apps", ",".join(entry["name"] for entry in release_matrix))
    return 0


def create_flat_aggregate(app_zips: list[tuple[str, Path]], aggregate_zip: Path) -> str:
    aggregate_zip.parent.mkdir(parents=True, exist_ok=True)
    if aggregate_zip.exists():
        aggregate_zip.unlink()

    seen: dict[str, str] = {}
    app_names = [app_name for app_name, _ in app_zips]
    with ZipFile(aggregate_zip, "w", ZIP_DEFLATED) as aggregate:
        write_install_all_script(aggregate, seen, app_names)
        for app_name in app_names:
            write_aggregate_app_install_script(aggregate, seen, app_name)
        # Legal files come from the commit being released. A package carried forward from an older release keeps the
        # legal files it was built with, which may differ from the current ones without being a conflict.
        for name, content in current_legal_entries(app_names).items():
            write_unique_zip_entry(aggregate, seen, name, content)
        for _, zip_path in app_zips:
            with ZipFile(zip_path, "r") as app_zip:
                for entry in sorted(app_zip.infolist(), key=lambda item: item.filename):
                    if entry.is_dir():
                        continue
                    if is_pdb_name(entry.filename):
                        raise SystemExit(f"Refusing to include PDB file in aggregate: {entry.filename}")
                    if is_root_app_install_name(entry.filename) or is_legal_entry_name(entry.filename):
                        continue
                    content = app_zip.read(entry.filename)
                    write_unique_zip_entry(aggregate, seen, entry.filename, content)

    return sha256_file(aggregate_zip)


def is_legal_entry_name(name: str) -> bool:
    normalized = name.replace("\\", "/")
    return normalized in REQUIRED_LEGAL_ARCHIVE_FILES or normalized.startswith(THIRD_PARTY_NOTICE_ARCHIVE_PREFIX)


def current_legal_entries(app_names: list[str]) -> dict[str, bytes]:
    """LICENSE.txt, NOTICE and the notices of the given apps, read from the repository at the released commit."""
    entries = {
        "LICENSE.txt": (REPO_ROOT / "LICENSE").read_bytes(),
        "NOTICE": (REPO_ROOT / "NOTICE").read_bytes(),
    }
    for app_name in app_names:
        for name in third_party_notice_archive_files(app_name):
            entries[name] = (THIRD_PARTY_NOTICE_DIRECTORY / name[len(THIRD_PARTY_NOTICE_ARCHIVE_PREFIX):]).read_bytes()
    return entries


def build_bundle_installer(
    factory_path: Path, payload_zip_paths: list[Path], final_dir: Path, tray_version: int
) -> Path:
    return stamp_installer(
        factory_path,
        BUNDLE_INSTALLER_NAME,
        payload_zip_paths,
        final_dir / installer_asset_name(BUNDLE_INSTALLER_NAME, tray_version),
    )


def require_manifest_keys(
    app_data: dict, keys: tuple[str, ...], description: str
) -> None:
    missing_keys = [key for key in keys if key not in app_data]
    if missing_keys:
        raise SystemExit(
            f"{description} is missing required field(s): {', '.join(missing_keys)}"
        )


def load_collected_profiles(
    input_root: Path,
    profile_ids: list[str],
    selected_apps: list[App],
) -> dict[str, dict]:
    required_profile_ids = set(profile_ids)
    expected_apps = {app.name for app in selected_apps}
    groups: dict[str, dict] = {}

    def add_app(profile_id: str, display_name: str, app_data: dict, root: Path) -> None:
        if profile_id not in PROFILES:
            raise SystemExit(f"Unknown profile in manifest: {profile_id}")
        if profile_id not in required_profile_ids:
            return
        if str(app_data.get("appId", "")) not in expected_apps:
            return

        zip_path = root / app_data["fileName"]
        if not zip_path.exists():
            raise SystemExit(f"Missing built asset for {app_data['appId']}: {zip_path}")

        require_manifest_keys(
            app_data,
            REQUIRED_APP_INSTALLER_MANIFEST_KEYS,
            f"Collected manifest for {app_data['appId']} under {root}",
        )
        installer_path = root / str(app_data["installerFileName"])
        if not installer_path.is_file():
            raise SystemExit(
                f"Missing built installer for {app_data['appId']}: {installer_path}"
            )

        group = groups.setdefault(
            profile_id,
            {
                "profile": profile_id,
                "displayName": display_name,
                "runtime": "win-x64",
                "apps": [],
            },
        )
        app_copy = dict(app_data)
        app_copy["zipPath"] = zip_path
        app_copy["installerPath"] = installer_path
        group["apps"].append(app_copy)

    for path in sorted(input_root.rglob("app-*.json")):
        manifest = json.loads(path.read_text(encoding="utf-8"))
        add_app(manifest["profile"], manifest["displayName"], manifest["app"], path.parent)

    if not groups:
        raise SystemExit(
            f"No selected app manifests found under {input_root} "
            f"for profile(s): {', '.join(profile_ids)}"
        )

    missing_profiles = required_profile_ids - set(groups)
    if missing_profiles:
        missing = [profile_id for profile_id in profile_ids if profile_id in missing_profiles]
        raise SystemExit(f"Missing profile manifest(s): {', '.join(missing)}")

    for profile_id, group in groups.items():
        found_apps = {app["appId"] for app in group["apps"]}
        missing_apps = expected_apps - found_apps
        if missing_apps:
            raise SystemExit(f"{profile_id} is missing app package(s): {', '.join(sorted(missing_apps))}")
        group["apps"].sort(key=lambda item: item["appId"])

    return groups


def profile_manifest_from_group(
    group: dict,
    aggregate_zip: Path,
    aggregate_sha: str,
    tray_version: int,
    commit_hash: str,
    bundle_installer_path: Path,
) -> dict:
    profile = PROFILES[group["profile"]]
    apps = []
    for app_data in group["apps"]:
        app_entry = {
            "appId": app_data["appId"],
            "version": app_data["version"],
            "source": app_data["source"],
            "commitHash": app_data.get("commitHash", ""),
        }
        app_entry["fileName"] = app_data["fileName"]
        app_entry["sha256"] = app_data["sha256"]
        app_entry["size"] = app_data.get("size", app_data["zipPath"].stat().st_size)
        app_entry["installerFileName"] = app_data["installerFileName"]
        app_entry["installerSha256"] = app_data["installerSha256"]
        app_entry["installerSize"] = app_data["installerSize"]
        apps.append(app_entry)

    manifest = {
        "profile": profile.id,
        "displayName": profile.display_name,
        "version": tray_version,
        "runtime": "win-x64",
        "aggregate": {
            "fileName": aggregate_zip.name,
            "sha256": aggregate_sha,
            "size": aggregate_zip.stat().st_size,
            "source": profile.build_source,
            "commitHash": commit_hash,
        },
        "bundleInstaller": {
            "fileName": bundle_installer_path.name,
            "sha256": sha256_file(bundle_installer_path),
            "size": bundle_installer_path.stat().st_size,
        },
        "apps": apps,
    }
    return manifest


def artifact_rows(manifests: list[dict]) -> list[dict]:
    rows: list[dict] = []
    for manifest in sorted(manifests, key=lambda item: item["profile"]):
        rows.append(
            {
                "profileId": manifest["profile"],
                "profile": manifest["displayName"],
                "appId": "TrayAppDotNET",
                "version": manifest["version"],
                "fileName": manifest["aggregate"]["fileName"],
                "sha256": manifest["aggregate"]["sha256"],
                "size": manifest["aggregate"]["size"],
                "source": manifest["aggregate"]["source"],
                "commitHash": manifest["aggregate"].get("commitHash", ""),
                "kind": "aggregate",
            }
        )
        for app in manifest["apps"]:
            rows.append(
                {
                    "profileId": manifest["profile"],
                    "profile": manifest["displayName"],
                    "appId": app["appId"],
                    "version": app["version"],
                    "fileName": app["fileName"],
                    "sha256": app["sha256"],
                    "size": app["size"],
                    "source": app["source"],
                    "commitHash": app.get("commitHash", ""),
                    "kind": "app",
                }
            )
        # Installers are always stamped at the release commit, so their rows carry the
        # aggregate build source and commit hash while the version identifies the payload.
        installer_source = manifest["aggregate"]["source"]
        installer_commit_hash = manifest["aggregate"].get("commitHash", "")
        for app in manifest["apps"]:
            rows.append(
                {
                    "profileId": manifest["profile"],
                    "profile": manifest["displayName"],
                    "appId": app["appId"],
                    "version": app["version"],
                    "fileName": app["installerFileName"],
                    "sha256": app["installerSha256"],
                    "size": app["installerSize"],
                    "source": installer_source,
                    "commitHash": installer_commit_hash,
                    "kind": "installer",
                }
            )
        rows.append(
            {
                "profileId": manifest["profile"],
                "profile": manifest["displayName"],
                "appId": BUNDLE_INSTALLER_NAME,
                "version": manifest["version"],
                "fileName": manifest["bundleInstaller"]["fileName"],
                "sha256": manifest["bundleInstaller"]["sha256"],
                "size": manifest["bundleInstaller"]["size"],
                "source": installer_source,
                "commitHash": installer_commit_hash,
                "kind": "installer",
            }
        )
    return rows


def artifact_table(rows: list[dict]) -> list[str]:
    lines = [
        "| App | Version | Asset | Commit Hash |",
        "| --- | --- | --- | --- |",
    ]
    for row in rows:
        lines.append(
            f"| {row['appId']} | {row['version']} | `{row['fileName']}` | "
            f"`{row['commitHash']}` |"
        )
    return lines


def ensure_release(repo: str, tag: str, title: str, target: str, notes_path: Path) -> None:
    exists = run(["gh", "release", "view", tag, "--repo", repo], check=False)
    if exists.returncode == 0:
        print(f"Release already exists for {tag}; notes will be updated and assets uploaded with --clobber.")
        cmd = ["gh", "release", "edit", tag, "--repo", repo, "--draft", "--title", title, "--notes-file", str(notes_path)]
        if target:
            cmd.extend(["--target", target])
        run(cmd)
        return

    cmd = [
        "gh",
        "release",
        "create",
        tag,
        "--repo",
        repo,
        "--draft",
        "--title",
        title,
        "--notes-file",
        str(notes_path),
    ]
    if target:
        cmd.extend(["--target", target])
    run(cmd)


def prune_release_assets(repo: str, tag: str, keep_names: set[str]) -> None:
    result = run(
        ["gh", "release", "view", tag, "--repo", repo, "--json", "assets"],
        capture=True,
        check=False,
    )
    if result.returncode != 0:
        return

    release = json.loads(result.stdout)
    for asset in release.get("assets", []):
        asset_name = str(asset.get("name", ""))
        if asset_name and asset_name not in keep_names:
            run(["gh", "release", "delete-asset", tag, asset_name, "--repo", repo, "--yes"])


def commit_section(repo: str, heading: str, commits: list[CommitEntry]) -> list[str]:
    lines: list[str] = [f"<div><b>{html.escape(heading)}</b></div>", "<ul>"]
    if not commits:
        lines.append("  <li>No commits.</li>")
    else:
        escaped_repo = html.escape(repo, quote=True)
        for commit in commits:
            full_sha = html.escape(commit.full_sha, quote=True)
            short_sha = html.escape(commit.short_sha)
            subject = html.escape(commit.subject)
            lines.append(
                f'  <li><a href="https://github.com/{escaped_repo}/commit/{full_sha}"><code>{short_sha}</code></a> {subject}</li>'
            )
    lines.extend(["</ul>", ""])
    return lines


def commit_affects_path(commit: CommitEntry, root_path: str) -> bool:
    path_prefix = f"{root_path}/"
    return any(
        path == root_path or path.startswith(path_prefix) for path in commit.paths
    )


def commits_for_path(commits: list[CommitEntry], root_path: str) -> list[CommitEntry]:
    return [
        commit for commit in commits if commit_affects_path(commit, root_path)
    ]


def release_note_section_roots() -> list[str]:
    return [COMMON_RELEASE_NOTES_ROOT, *sorted(app.name for app in APPS)]


def release_note_sections(
    commits: list[CommitEntry],
    app_commits: dict[str, list[CommitEntry]],
) -> list[tuple[str, list[CommitEntry]]]:
    """Groups commits under Global, Common and every app.

    Global and Common draw on the commits since the previous release.
    Each app draws only on its app_commits entry, so an app whose package was carried forward lists none.
    """
    section_roots = release_note_section_roots()
    global_commits = [
        commit
        for commit in commits
        if all(commit_affects_path(commit, root_path) for root_path in section_roots)
    ]
    global_shas = {commit.full_sha for commit in global_commits}

    sections: list[tuple[str, list[CommitEntry]]] = [("Global", global_commits)]
    sections.append(
        (
            "Common",
            [
                commit
                for commit in commits_for_path(commits, COMMON_RELEASE_NOTES_ROOT)
                if commit.full_sha not in global_shas
            ],
        )
    )
    for app_name in sorted(app.name for app in APPS):
        sections.append(
            (
                app_name,
                [
                    commit
                    for commit in commits_for_path(
                        app_commits.get(app_name, []), app_name
                    )
                    if commit.full_sha not in global_shas
                ],
            )
        )
    return sections


def commit_sections(
    repo: str, sections: list[tuple[str, list[CommitEntry]]]
) -> list[str]:
    lines: list[str] = []
    for heading, section_commits in sections:
        lines.extend(commit_section(repo, heading, section_commits))
    return lines


def pull_request_commits(
    commits: list[CommitEntry],
    sections: list[tuple[str, list[CommitEntry]]],
) -> list[CommitEntry]:
    """Lists the commits whose pull requests the release notes name.

    These are the listed commits plus those since the previous release that touch neither Common nor any app.
    """
    selected_commits: dict[str, CommitEntry] = {}
    for _heading, section_commits in sections:
        for commit in section_commits:
            selected_commits.setdefault(commit.full_sha, commit)

    section_roots = release_note_section_roots()
    for commit in commits:
        if not any(
            commit_affects_path(commit, root_path) for root_path in section_roots
        ):
            selected_commits.setdefault(commit.full_sha, commit)
    return list(selected_commits.values())


def released_app_commits(
    repo: str,
    groups: dict[str, dict],
    commits: list[CommitEntry],
    target: str,
) -> dict[str, list[CommitEntry]]:
    """Maps each app built in this release to the commits since its replaced package was built.

    A carried-forward package ships no new commits, so its app gets no entry.
    For an app skipped in earlier releases, that reaches back past the previous release to its last build.
    """
    target_ref = target.strip() or "HEAD"
    releases: list[dict] | None = None
    commits_by_base: dict[str, list[CommitEntry] | None] = {}
    app_commits: dict[str, list[CommitEntry]] = {}
    for profile_id in sorted(groups):
        profile = PROFILES[profile_id]
        for app_data in groups[profile_id]["apps"]:
            if str(app_data["source"]).startswith(REUSED_PACKAGE_SOURCE_PREFIX):
                continue

            app = app_by_name(str(app_data["appId"]))
            if releases is None:
                releases = published_releases(repo)
            previous_asset = latest_published_app_asset(releases, app, profile)
            base_commit = (
                ""
                if previous_asset is None
                else published_app_build_commit(repo, previous_asset, app, profile)
            )
            if not base_commit:
                app_commits[app.name] = commits
                continue

            if base_commit not in commits_by_base:
                commits_by_base[base_commit] = commit_log(
                    f"{base_commit}..{target_ref}"
                )
            base_commits = commits_by_base[base_commit]
            app_commits[app.name] = commits if base_commits is None else base_commits
    return app_commits


def pull_request_list(pull_requests: list[PullRequestEntry]) -> list[str]:
    if not pull_requests:
        return ["- No pull requests found."]

    return [
        f"- {pull_request.title} by {pull_request.author_username} in {pull_request.url}"
        for pull_request in pull_requests
    ]


def truncate_release_notes(notes: str) -> str:
    if len(notes) <= MAX_RELEASE_NOTES_CHARACTERS:
        return notes

    suffix = f"\n\n{RELEASE_NOTES_TRUNCATION_NOTICE}"
    prefix = notes[: MAX_RELEASE_NOTES_CHARACTERS - len(suffix)]
    newline_index = prefix.rfind("\n")
    if newline_index > 0:
        prefix = prefix[:newline_index]
    prefix = prefix.rstrip()

    while True:
        unclosed_lists = max(0, prefix.count("<ul>") - prefix.count("</ul>"))
        closing_tags = "" if unclosed_lists == 0 else "\n" + "\n".join("</ul>" for _ in range(unclosed_lists))
        if len(prefix) + len(closing_tags) + len(suffix) <= MAX_RELEASE_NOTES_CHARACTERS:
            return prefix + closing_tags + suffix

        newline_index = prefix.rfind("\n")
        if newline_index <= 0:
            available_characters = MAX_RELEASE_NOTES_CHARACTERS - len(closing_tags) - len(suffix)
            return prefix[:available_characters].rstrip() + closing_tags + suffix
        prefix = prefix[:newline_index].rstrip()


def write_notes(
    path: Path,
    rows: list[dict],
    repo: str,
    previous_release: dict | None,
    sections: list[tuple[str, list[CommitEntry]]],
    pull_requests: list[PullRequestEntry],
) -> None:
    lines = [
        "This release is auto-generated. The following artifacts have been compiled against Windows 11 as self-contained Native AOT applications",
        "",
        "## Version Info",
        "",
        *artifact_table(rows),
        "",
        "## Pull Requests",
        "",
        *pull_request_list(pull_requests),
        "",
        f"## Commits since {release_display_ref(previous_release)}",
        "",
        *commit_sections(repo, sections),
    ]
    path.write_text(truncate_release_notes("\n".join(lines)), encoding="utf-8")


def write_summary(rows: list[dict]) -> None:
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if not summary_path:
        return
    lines = [
        "## Publish Artifacts",
        "",
        *artifact_table(rows),
        "",
    ]
    with Path(summary_path).open("a", encoding="utf-8") as summary:
        summary.write("\n".join(lines))


def write_versions_manifest(path: Path, rows: list[dict], tray_version: int, repo: str, release_tag: str) -> None:
    root = ET.Element(
        "versions",
        {
            "version": str(tray_version),
            "runtime": "win-x64",
        },
    )
    ET.SubElement(
        root,
        "release",
        {
            "repository": repo,
            "tag": release_tag,
            "name": f"TrayAppDotNET {tray_version}",
        },
    )
    # The apps this release carries. The version endpoint requires exactly these, so publishing a new app needs
    # no endpoint redeploy, and an app missing from the endpoint's own catalog never blocks deployment.
    applications = ET.SubElement(root, "applications")
    for app_id in dict.fromkeys(str(row["appId"]) for row in rows if row["kind"] == "app"):
        ET.SubElement(applications, "application", {"appId": app_id})
    artifacts = ET.SubElement(root, "artifacts")
    for row in rows:
        ET.SubElement(
            artifacts,
            "artifact",
            {
                "profile": str(row["profileId"]),
                "profileName": str(row["profile"]),
                "kind": str(row["kind"]),
                "appId": str(row["appId"]),
                "version": str(row["version"]),
                "fileName": str(row["fileName"]),
                "sha256": str(row["sha256"]),
                "size": str(row["size"]),
                "source": str(row["source"]),
                "commitHash": str(row["commitHash"]),
            },
        )

    tree = ET.ElementTree(root)
    ET.indent(tree, space="  ")
    tree.write(path, encoding="utf-8", xml_declaration=True)


def publish_release(args: argparse.Namespace) -> int:
    input_root = Path(args.input_root)
    profile_ids = parse_profile_ids(args.profiles)
    selected_apps = parse_app_names(args.apps, argument_name="--apps")
    groups = load_collected_profiles(input_root, profile_ids, selected_apps)
    previous_release = latest_release(
        args.repo,
        missing_message=(
            "No latest published release found; defaulting TrayAppDotNET version "
            f"to {INITIAL_RELEASE_VERSION}."
        ),
    )
    requested_tag = args.release_tag.strip()
    if args.tray_version.strip():
        tray_version = int(args.tray_version)
    elif requested_tag:
        # A tag alone names the version: the endpoint requires the two to agree
        tray_version = release_tag_version(requested_tag)
    else:
        tray_version = default_tray_version(previous_release)
    release_tag = validate_release_tag(requested_tag or f"TrayAppDotNET_{tray_version}", tray_version)
    aggregate_commit_hash = try_resolve_git_commit(args.target.strip() or "HEAD")

    final_dir = input_root / "_release"
    final_dir.mkdir(parents=True, exist_ok=True)

    manifests: list[dict] = []
    upload_assets: list[Path] = []
    for profile_id in sorted(groups):
        group = groups[profile_id]
        profile = PROFILES[profile_id]
        aggregate_zip = final_dir / aggregate_asset_name(tray_version, profile)
        # Group apps are sorted by appId, so the bundle payload order is deterministic.
        app_zip_paths = [app_data["zipPath"] for app_data in group["apps"]]
        app_installer_paths = [app_data["installerPath"] for app_data in group["apps"]]
        app_zips = [(app_data["appId"], app_data["zipPath"]) for app_data in group["apps"]]
        aggregate_sha = create_flat_aggregate(app_zips, aggregate_zip)
        factory_path = resolve_installer_factory(
            args.installer_factory,
            Path(args.output_root),
            profile,
            aggregate_commit_hash,
        )
        bundle_installer_path = build_bundle_installer(
            factory_path, app_zip_paths, final_dir, tray_version
        )
        manifests.append(
            profile_manifest_from_group(
                group,
                aggregate_zip,
                aggregate_sha,
                tray_version,
                aggregate_commit_hash,
                bundle_installer_path,
            )
        )
        upload_assets.append(aggregate_zip)
        upload_assets.append(bundle_installer_path)
        upload_assets.extend(app_zip_paths)
        upload_assets.extend(app_installer_paths)

    rows = artifact_rows(manifests)

    notes_path = final_dir / "release-notes.md"
    versions_path = final_dir / "versions.xml"
    release_notes_base = previous_release
    if release_notes_base is None:
        previous_tag = latest_reachable_release_tag(args.target)
        if previous_tag:
            print(f"No published release exists; generating release notes since {previous_tag}.")
            release_notes_base = {"tag_name": previous_tag}

    commits = commits_since_release(release_notes_base, args.target)
    sections = release_note_sections(
        commits,
        released_app_commits(args.repo, groups, commits, args.target),
    )
    pull_requests = pull_requests_for_commits(
        args.repo, pull_request_commits(commits, sections)
    )
    write_notes(
        notes_path, rows, args.repo, release_notes_base, sections, pull_requests
    )
    write_versions_manifest(versions_path, rows, tray_version, args.repo, release_tag)
    write_summary(rows)

    ensure_release(
        args.repo,
        release_tag,
        f"TrayAppDotNET {tray_version}",
        args.target,
        notes_path,
    )

    upload_assets.append(versions_path)
    upload_assets = list(dict.fromkeys(upload_assets))
    prune_release_assets(args.repo, release_tag, {path.name for path in upload_assets})

    run(["gh", "release", "upload", release_tag, *[str(path) for path in upload_assets], "--repo", args.repo, "--clobber"])

    print("Published draft release assets:")
    for row in rows:
        print(f"- {row['profile']}: {row['fileName']}")
    print(f"- {versions_path.name}")
    return 0


def describe_app(args: argparse.Namespace) -> int:
    """Writes one catalog app's CI settings as step outputs, so workflows need no app list of their own."""
    app = app_by_name(args.app_name.strip())
    set_github_output("name", app.name)
    set_github_output("slug", app.slug)
    set_github_output("display_name", app.display_name)
    set_github_output("checkout_submodules", str(app.checkout_submodules).lower())
    set_github_output("requires_msvc", str(app.requires_msvc).lower())
    return 0


def main() -> int:
    args = parse_args()
    if args.phase == "build-app-profile":
        return build_app_profile(args)
    if args.phase == "describe-app":
        return describe_app(args)
    if args.phase == "build-installer-factory":
        return build_installer_factory_profile(args)
    if args.phase == "plan-publish":
        return plan_publish(args)
    return publish_release(args)


if __name__ == "__main__":
    raise SystemExit(main())
